CREATE OR REPLACE FUNCTION mbt_validate_rate_card_version_activation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  band_count integer;
  invalid_count integer;
BEGIN
  IF NEW.status <> 'active'
     OR (TG_OP = 'UPDATE' AND OLD.status = 'active') THEN
    RETURN NEW;
  END IF;

  WITH ordered_bands AS (
    SELECT minimum_metres,
           maximum_metres,
           row_number() OVER (
             PARTITION BY service_code,
                          COALESCE(bin_type_id, '00000000-0000-0000-0000-000000000000'::uuid)
             ORDER BY minimum_metres, sequence_number, rate_distance_band_id
           ) AS band_position,
           count(*) OVER (
             PARTITION BY service_code,
                          COALESCE(bin_type_id, '00000000-0000-0000-0000-000000000000'::uuid)
           ) AS group_size,
           lag(maximum_metres) OVER (
             PARTITION BY service_code,
                          COALESCE(bin_type_id, '00000000-0000-0000-0000-000000000000'::uuid)
             ORDER BY minimum_metres, sequence_number, rate_distance_band_id
           ) AS previous_maximum
      FROM mbt_rate_distance_bands
     WHERE rate_card_version_id = NEW.rate_card_version_id
  )
  SELECT count(*)::integer,
         count(*) FILTER (
           WHERE (band_position = 1 AND minimum_metres <> 0)
              OR (band_position > 1 AND previous_maximum IS DISTINCT FROM minimum_metres)
              OR (band_position < group_size AND maximum_metres IS NULL)
              OR (band_position = group_size AND maximum_metres IS NOT NULL)
         )::integer
    INTO band_count, invalid_count
    FROM ordered_bands;

  IF band_count = 0 OR invalid_count > 0 THEN
    RAISE EXCEPTION 'rate-card version % has invalid distance bands',
      NEW.rate_card_version_id
      USING ERRCODE = '23514',
            CONSTRAINT = 'mbt_rate_card_versions_distance_bands_valid';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_mbt_rate_card_versions_activation_valid
  ON mbt_rate_card_versions;
CREATE TRIGGER trg_mbt_rate_card_versions_activation_valid
  BEFORE INSERT OR UPDATE OF status ON mbt_rate_card_versions
  FOR EACH ROW EXECUTE FUNCTION mbt_validate_rate_card_version_activation();

CREATE OR REPLACE FUNCTION mbt_stamp_rate_version_first_use()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  entity_type text;
  entity_id uuid;
  version_status text;
BEGIN
  IF TG_TABLE_NAME = 'mbt_quotes' THEN
    IF NEW.status = 'draft' THEN
      RETURN NEW;
    END IF;
    entity_type := 'quote';
    entity_id := NEW.quote_id;
  ELSIF TG_TABLE_NAME = 'mbt_contracts' THEN
    IF NEW.status = 'draft' THEN
      RETURN NEW;
    END IF;
    entity_type := 'contract';
    entity_id := NEW.contract_id;
  ELSE
    RAISE EXCEPTION 'unsupported rate-version consumer %', TG_TABLE_NAME
      USING ERRCODE = '55000';
  END IF;

  SELECT status
    INTO version_status
    FROM mbt_rate_card_versions
   WHERE rate_card_version_id = NEW.rate_card_version_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;
  IF version_status <> 'active' THEN
    RAISE EXCEPTION '% % cannot use non-active rate-card version %',
      entity_type, entity_id, NEW.rate_card_version_id
      USING ERRCODE = '55000';
  END IF;

  UPDATE mbt_rate_card_versions
     SET first_used_at = now(),
         first_used_entity_type = entity_type,
         first_used_entity_id = entity_id
   WHERE rate_card_version_id = NEW.rate_card_version_id
     AND first_used_at IS NULL;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_mbt_quotes_stamp_rate_first_use
  ON mbt_quotes;
CREATE TRIGGER trg_mbt_quotes_stamp_rate_first_use
  BEFORE INSERT OR UPDATE OF status, rate_card_version_id ON mbt_quotes
  FOR EACH ROW EXECUTE FUNCTION mbt_stamp_rate_version_first_use();

DROP TRIGGER IF EXISTS trg_mbt_contracts_stamp_rate_first_use
  ON mbt_contracts;
CREATE TRIGGER trg_mbt_contracts_stamp_rate_first_use
  BEFORE INSERT OR UPDATE OF status, rate_card_version_id ON mbt_contracts
  FOR EACH ROW EXECUTE FUNCTION mbt_stamp_rate_version_first_use();

CREATE OR REPLACE FUNCTION mbt_reject_used_rate_version_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF OLD.first_used_at IS NOT NULL THEN
    RAISE EXCEPTION 'used rate-card version % is immutable', OLD.rate_card_version_id
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION mbt_reject_used_rate_child_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  old_version_id uuid;
  new_version_id uuid;
  used_at timestamptz;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    old_version_id := OLD.rate_card_version_id;
    SELECT first_used_at
      INTO used_at
      FROM mbt_rate_card_versions
     WHERE rate_card_version_id = old_version_id;
    IF used_at IS NOT NULL THEN
      RAISE EXCEPTION 'pricing rows for used rate-card version % are immutable', old_version_id
        USING ERRCODE = '55000';
    END IF;
  END IF;

  IF TG_OP <> 'DELETE' THEN
    new_version_id := NEW.rate_card_version_id;
    IF old_version_id IS DISTINCT FROM new_version_id THEN
      SELECT first_used_at
        INTO used_at
        FROM mbt_rate_card_versions
       WHERE rate_card_version_id = new_version_id;
      IF used_at IS NOT NULL THEN
        RAISE EXCEPTION 'pricing rows for used rate-card version % are immutable', new_version_id
          USING ERRCODE = '55000';
      END IF;
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_mbt_rate_card_versions_used_immutable
  ON mbt_rate_card_versions;
CREATE TRIGGER trg_mbt_rate_card_versions_used_immutable
  BEFORE UPDATE OR DELETE ON mbt_rate_card_versions
  FOR EACH ROW EXECUTE FUNCTION mbt_reject_used_rate_version_mutation();

