CREATE OR REPLACE FUNCTION mbt_reject_completed_visit_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF OLD.status = 'completed' THEN
    RAISE EXCEPTION 'completed service visit % is immutable', OLD.service_visit_id
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_mbt_service_visits_completed_immutable
  ON mbt_service_visits;
CREATE TRIGGER trg_mbt_service_visits_completed_immutable
  BEFORE UPDATE OR DELETE ON mbt_service_visits
  FOR EACH ROW EXECUTE FUNCTION mbt_reject_completed_visit_mutation();

CREATE OR REPLACE FUNCTION mbt_reject_completed_visit_child_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  parent_visit_id uuid;
  parent_status text;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    parent_visit_id := OLD.service_visit_id;
    SELECT status
      INTO parent_status
      FROM mbt_service_visits
     WHERE service_visit_id = parent_visit_id;
    IF parent_status = 'completed' THEN
      RAISE EXCEPTION 'operational history for completed service visit % is immutable', parent_visit_id
        USING ERRCODE = '55000';
    END IF;
  END IF;

  IF TG_OP <> 'DELETE'
     AND (TG_OP = 'INSERT' OR NEW.service_visit_id IS DISTINCT FROM OLD.service_visit_id) THEN
    parent_visit_id := NEW.service_visit_id;
    SELECT status
      INTO parent_status
      FROM mbt_service_visits
     WHERE service_visit_id = parent_visit_id;
    IF parent_status = 'completed' THEN
      RAISE EXCEPTION 'operational history for completed service visit % is immutable', parent_visit_id
        USING ERRCODE = '55000';
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

