CREATE OR REPLACE FUNCTION mbt_reject_terminal_visit_reservation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  visit_status text;
BEGIN
  SELECT status
    INTO visit_status
    FROM mbt_service_visits
   WHERE service_visit_id = NEW.visit_id;
  IF visit_status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION '% service visit % cannot accept an asset reservation',
      visit_status, NEW.visit_id
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;

