COMMENT ON TABLE mbt_rate_card_versions IS
  'Effective-dated MBT pricing versions. Marking first_used_at locks the version and every pricing child row.';

COMMENT ON TABLE mbt_service_visits IS
  'Independently schedulable MBT work projected to Dispatch only after later-phase capabilities are enabled.';

COMMENT ON TABLE mbt_bin_asset_reservations IS
  'Exact-bin reservations. Partial unique indexes prevent one asset or one visit slot from being reserved twice.';
